/* Two views of the existing approved gemstone evaluators. */
(()=>{'use strict';const $=id=>document.getElementById(id);let last='';function refresh(){const mode=$('gem-mode')?.value;if(!mode||!window.currentKPModel?.ready)return;const other=mode==='kp'?'vedic':'kp',stones=Object.fromEntries(['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'].map(id=>[id,$('gem-stone-'+id)?.value||'']));try{const data=KPGemstones.evaluate(currentKPModel,{mode:other,required:$('gem-required').value,excluded:'',method:'fourfold',roles:['planet','star','sub'],excludeRetrograde:true,excludeCombust:true,stones});const signature=JSON.stringify(data);if(signature===last)return;last=signature;const panel=$('gem-companion-panel');panel.replaceChildren();const title=document.createElement('h3');title.textContent=other==='vedic'?'According to Vedic Jyotish · houses 1, 5, 11':'According to KP · approved XI cusp rule';panel.append(title);if(data.proof){const proof=document.createElement('p');proof.textContent=data.proof;panel.append(proof);}const table=document.createElement('table');table.className='kp-feature-table';table.innerHTML='<thead><tr><th>Planet</th><th>Gemstone</th><th>Significator evidence</th></tr></thead><tbody></tbody>';for(const row of data.results.filter(r=>r.qualifies)){const tr=document.createElement('tr');for(const value of [KPDisplay.names[row.id]||row.id,row.stone,other==='vedic'?'Owns houses '+row.ownership.join(', '):'Houses '+row.houses.join(', ')]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.tBodies[0].append(tr);}if(!table.tBodies[0].rows.length){const p=document.createElement('p');p.textContent='No gemstone qualifies under this approved rule.';panel.append(p);}else panel.append(table);const note=document.createElement('p');note.textContent='Mantra, worship and donation: consult the Original Ratna guidance below.';panel.append(note);}catch(e){$('gem-companion-panel').textContent=e.message;}}
function init(){const card=$('gemstones')?.querySelector('.gem-simple-card');if(!card)return;const panel=document.createElement('section');panel.id='gem-companion-panel';panel.className='gem-companion-panel';const heading=document.createElement('h3');heading.id='gem-primary-panel-title';heading.textContent='According to KP / Vedic · selected rule';$('gem-status').before(heading);card.querySelector('details').before(panel);new MutationObserver(refresh).observe($('gem-results'),{childList:true});$('gem-mode').addEventListener('change',()=>{last='';refresh();});const old=KPGemstones;window.KPGemstones=Object.freeze({...old,snapshot(){refresh();return old.snapshot()+'<section class="gem-companion-panel">'+panel.innerHTML+'</section>';}});refresh();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,150));else init();})();
